package mapper

import (
	"fmt"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// ChunkMigrateInput is the mapper's normalized view of a legacy chunk,
// shaped to feed DocumentService.MigrateChunks. It deliberately omits
// embedding state (Phase 6 handles that) and any legacy chunk_metadata
// JSON — the new platform's per-row schema does not store either at
// this layer.
//
// LegacyID is the synthesized "legacy:chunk:<int>" key shared with the
// rejection-report writer and the embeddings phase (Phase 6 needs it to
// resolve the new chunk UUID via the chunk_legacy_id_map sidecar).
type ChunkMigrateInput struct {
	LegacyID   string // "legacy:chunk:<int>"
	ChunkIndex int32
	Text       string
	StartChar  *int32
	EndChar    *int32
}

// ChunksToMigrateInputs maps a slice of legacy chunks for a single
// document into the proto-shaped input slice. Preserves input ordering
// (the reader emits ORDER BY chunk_index ASC) and never returns nil for
// a non-empty input.
func ChunksToMigrateInputs(chunks []legacy.LegacyChunk) []ChunkMigrateInput {
	if len(chunks) == 0 {
		return nil
	}
	out := make([]ChunkMigrateInput, 0, len(chunks))
	for _, c := range chunks {
		out = append(out, ChunkMigrateInput{
			LegacyID:   fmt.Sprintf("legacy:chunk:%d", c.LegacyID),
			ChunkIndex: c.ChunkIndex,
			Text:       c.Content,
			StartChar:  c.StartChar,
			EndChar:    c.EndChar,
		})
	}
	return out
}


