package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/timestamppb"

	corpusv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/files/corpus/v1"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// Severity tags how blocking a RejectionNote is when it reaches the
// rejection-report sidecar (Task 19). The constants mirror
// rejection.Severity{Warn,Error}; we redeclare them here so the mapper
// package does not import the rejection package (would be a cycle when
// rejection later wants to consume the mapper output for tests).
const (
	SeverityWarn  = "warn"
	SeverityError = "error"
)

// RejectionNote is a soft-warning record emitted by mappers / apply
// layers when a legacy row has a value that is being downgraded,
// defaulted, deferred, or skipped. Notes are written to the rejection-
// report sidecar (Task 19) by the apply layer.
//
// Severity:
//   - "warn"  (default) — the row still migrated; the note records a
//     downgrade / deferred resolution / dropped property.
//   - "error" — the row was DROPPED (entity skipped, edge skipped,
//     RPC failed). The migrator did not write the row to the new
//     platform.
//
// An empty Severity is treated as "warn" by the writer for backward
// compatibility with mapper-emitted notes.
type RejectionNote struct {
	LegacyID string
	Reason   string
	Severity string
}

// CorpusMigrateInput is the mapper's normalized view of a legacy corpus,
// shaped to feed CorpusService.MigrateCorpus.
type CorpusMigrateInput struct {
	LegacyID    string
	Name        string
	Description string
	Visibility  corpusv1.CorpusVisibility
	OwnerUserID string // empty until the user-resolution layer lands
	CreatedAt   *timestamppb.Timestamp
}

// CorpusToMigrateInput maps a legacy.LegacyCorpus to a MigrateCorpus RPC
// input plus a slice of soft rejection notes for visibility downgrades
// or owner-resolution deferrals.
//
// Visibility translation (per files corpus proto):
//
//   - "private" → CORPUS_VISIBILITY_PRIVATE
//   - "team"    → CORPUS_VISIBILITY_TEAM
//   - "shared"  → CORPUS_VISIBILITY_TEAM (with a deprecation note —
//     spec §11 dropped per-user/per-group sharing in v1)
//   - any other → CORPUS_VISIBILITY_PRIVATE (with an unknown-value note)
//
// owner_user_id is intentionally left empty here. Legacy users.id is an
// INTEGER FK; the new platform stores owner as a UUID. The user-
// resolution layer (sub-PR 8 follow-up / cutover script) will backfill
// owner_user_id post-hoc. Every row produces a deferred-owner note.
func CorpusToMigrateInput(lc legacy.LegacyCorpus) (CorpusMigrateInput, []RejectionNote) {
	legacyID := fmt.Sprintf("legacy:corpus:%d", lc.LegacyID)
	var notes []RejectionNote

	var vis corpusv1.CorpusVisibility
	switch lc.Visibility {
	case "private":
		vis = corpusv1.CorpusVisibility_CORPUS_VISIBILITY_PRIVATE
	case "team":
		vis = corpusv1.CorpusVisibility_CORPUS_VISIBILITY_TEAM
	case "shared":
		vis = corpusv1.CorpusVisibility_CORPUS_VISIBILITY_TEAM
		notes = append(notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   "shared visibility deprecated; mapped to team",
		})
	default:
		vis = corpusv1.CorpusVisibility_CORPUS_VISIBILITY_PRIVATE
		notes = append(notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("unknown visibility %q; defaulted to private", lc.Visibility),
		})
	}

	// TODO(sub-PR 8 follow-up): resolve legacy users.id (int) → new
	// identity.users.id (UUID) and populate owner_user_id. Until then,
	// every migrated corpus emits a deferred-owner note.
	notes = append(notes, RejectionNote{
		LegacyID: legacyID,
		Reason:   "owner_user_id deferred — legacy int FK not resolved to new UUID",
	})

	return CorpusMigrateInput{
		LegacyID:    legacyID,
		Name:        lc.Name,
		Description: lc.Description,
		Visibility:  vis,
		OwnerUserID: "",
		CreatedAt:   timestamppb.New(lc.CreatedAt),
	}, notes
}


