package mapper

import (
	"fmt"
	"strings"

	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// DocumentMigrateInput is the mapper's normalized view of a legacy
// document, shaped to feed DocumentService.MigrateUpload.
//
// CorpusID is the new-platform UUID resolved upstream from the corpus
// legacy_id_map (Phase 3 sidecar). UploadedBy is left empty when the
// legacy row has a NULL uploaded_by — the apply layer skips those rows
// because files-svc rejects empty uploaded_by with INVALID_ARGUMENT.
type DocumentMigrateInput struct {
	LegacyID         string // "legacy:document:<int>"
	CorpusID         string // new-platform corpus UUID
	OriginalFilename string
	MIMEType         string // RFC-6838 media type
	SizeBytes        int64
	UploadedBy       string // new-platform user UUID; empty until user-resolution lands
	CreatedAt        *timestamppb.Timestamp
}

// DocumentToMigrateInput maps a legacy.LegacyDocument to a MigrateUpload
// RPC input plus a slice of soft rejection notes for owner-resolution
// deferrals and unknown file types.
//
// Note ordering is intentional: deferred-owner / unknown-mime notes
// always precede any per-row downstream notes appended by the apply
// layer (size mismatch, RPC failure, etc.).
//
// uploaded_by is intentionally left empty for the same reason as
// CorpusToMigrateInput: legacy users.id is an INTEGER FK, the new
// platform stores uploaded_by as a UUID. The user-resolution layer is
// deferred; the apply layer skips legacy rows with a nil uploaded_by
// because files-svc requires a non-empty value.
func DocumentToMigrateInput(ld legacy.LegacyDocument, corpusUUID string) (DocumentMigrateInput, []RejectionNote) {
	legacyID := fmt.Sprintf("legacy:document:%d", ld.LegacyID)
	var notes []RejectionNote

	mime := resolveMIMEType(ld.MIMEType)
	if mime == "application/octet-stream" && ld.MIMEType != "" {
		notes = append(notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("unknown legacy file_type %q; defaulted to application/octet-stream", ld.MIMEType),
		})
	}

	notes = append(notes, RejectionNote{
		LegacyID: legacyID,
		Reason:   "uploaded_by deferred — legacy int FK not resolved to new UUID",
	})

	return DocumentMigrateInput{
		LegacyID:         legacyID,
		CorpusID:         corpusUUID,
		OriginalFilename: ld.OriginalFilename,
		MIMEType:         mime,
		SizeBytes:        ld.SizeBytes,
		UploadedBy:       "",
		CreatedAt:        timestamppb.New(ld.CreatedAt),
	}, notes
}

// resolveMIMEType maps the legacy `documents.file_type` short tag (e.g.
// "pdf", "docx", "txt") to a real RFC-6838 mime type. Unknown / empty
// values resolve to application/octet-stream — the new-platform schema
// uses that as the safe default for opaque binaries.
func resolveMIMEType(legacyFileType string) string {
	switch strings.ToLower(strings.TrimSpace(legacyFileType)) {
	case "":
		return "application/octet-stream"
	case "pdf":
		return "application/pdf"
	case "txt", "text":
		return "text/plain"
	case "md", "markdown":
		return "text/markdown"
	case "html", "htm":
		return "text/html"
	case "csv":
		return "text/csv"
	case "json":
		return "application/json"
	case "doc":
		return "application/msword"
	case "docx":
		return "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
	case "xls":
		return "application/vnd.ms-excel"
	case "xlsx":
		return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
	case "ppt":
		return "application/vnd.ms-powerpoint"
	case "pptx":
		return "application/vnd.openxmlformats-officedocument.presentationml.presentation"
	case "png":
		return "image/png"
	case "jpg", "jpeg":
		return "image/jpeg"
	case "gif":
		return "image/gif"
	case "mp3":
		return "audio/mpeg"
	case "wav":
		return "audio/wav"
	case "mp4":
		return "video/mp4"
	default:
		// Already a real mime type? Pass it through.
		if strings.Contains(legacyFileType, "/") {
			return legacyFileType
		}
		return "application/octet-stream"
	}
}

// SanitizeStorageKey strips path separators and other characters that
// would break a flat MinIO key from a legacy filename. Empty input
// yields "file" (so the key always carries a trailing component).
func SanitizeStorageKey(filename string) string {
	if filename == "" {
		return "file"
	}
	mapping := func(r rune) rune {
		switch {
		case r == '/' || r == '\\':
			return '_'
		case r < 0x20 || r == 0x7f:
			return '_'
		default:
			return r
		}
	}
	out := strings.Map(mapping, filename)
	out = strings.TrimSpace(out)
	if out == "" {
		return "file"
	}
	return out
}


--- services/migrator-files/internal/mapper/edge.go (198 lines) ---
package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/structpb"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EdgeMigrateInput is the mapper's normalized view of a legacy Memgraph
// relationship, shaped to feed EdgeService.MigrateEdge.
//
// SourceEntityID / TargetEntityID are the new-platform UUIDs resolved
// via the Phase 7 sidecar (entity_map.json), keyed by
// "legacy:entity:<int64>". RelationshipTypeID is the new-platform UUID
// resolved via the Phase 2 sidecar (relationship_type_map.json), keyed
// by "legacy:rel-type:<legacyOrgID>:<RelationshipType>" (the same shape
// MemgraphReader.ListRelationshipTypes mints — see memgraph.go).
//
// When any of the three resolutions fails the caller MUST drop the
// edge — files-svc rejects MigrateEdge requests with empty type_id,
// source_id, or target_id (INVALID_ARGUMENT).
//
// CreatedAt is captured for symmetry with the rest of the migrator;
// MigrateEdgeRequest does not currently accept it (see edge.proto), so
// the apply layer does not forward it. We still surface it here for
// future-proofing — when the proto adds a created_at field, no mapper
// change is needed.
type EdgeMigrateInput struct {
	LegacyID           string
	SourceEntityID     string
	TargetEntityID     string
	RelationshipTypeID string
	Properties         *structpb.Struct
	CreatedAt          *timestamppb.Timestamp
}

// EdgeToMigrateInput maps a legacy.LegacyEdge to a MigrateEdge RPC input
// plus a slice of soft rejection notes. The third return value is a
// hard `skip` flag — when true the caller MUST drop the edge.
//
// Source/target resolution:
//
//	Each endpoint legacy_id is looked up in entityIDLookup (Phase 7
//	sidecar). When either is missing OR resolves to the same new
//	UUID (self-loop) we emit a rejection note and skip — files-svc
//	rejects self-loops with INVALID_ARGUMENT to match the
//	entity_edges CHECK (source_id <> target_id) schema constraint.
//
// Type resolution:
//
//	The legacy type is the Memgraph edge label (type(r)). Phase 2
//	bootstrapped each distinct value into files.relationship_types
//	and emitted relationship_type_map.json keyed by
//	"legacy:rel-type:<legacyOrgID>:<RelationshipType>" (see
//	memgraph.go::ListRelationshipTypes for the canonical key shape).
//	Unmapped types yield a rejection note + skip.
//
// Properties conversion:
//
//	legacy.LegacyEdge.Properties is map[string]any; we convert to
//	*structpb.Struct using normalizeStructValue (shared with
//	EntityToMigrateInput). Values with unsupported types are dropped
//	with a soft note and the edge still migrates with a partial
//	property set.
//
// legacyOrgID is the integer organization_id used when Phase 2 minted
// the relationship-type LegacyID keys — pass the same value here so
// lookups hit.
func EdgeToMigrateInput(
	le legacy.LegacyEdge,
	legacyOrgID int,
	entityIDLookup map[string]string,
	relTypeIDLookup map[string]string,
) (EdgeMigrateInput, []RejectionNote, bool) {
	var notes []RejectionNote

	out := EdgeMigrateInput{
		LegacyID: le.LegacyID,
	}
	if !le.CreatedAt.IsZero() {
		out.CreatedAt = timestamppb.New(le.CreatedAt)
	}

	skip := false

	// 1. Resolve source.
	if le.SourceLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   "legacy edge has empty source legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := entityIDLookup[le.SourceLegacyID]; ok && newID != "" {
		out.SourceEntityID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   fmt.Sprintf("source entity %s not found in entity_map; skipping edge", le.SourceLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	// 2. Resolve target.
	if le.TargetLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   "legacy edge has empty target legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := entityIDLookup[le.TargetLegacyID]; ok && newID != "" {
		out.TargetEntityID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   fmt.Sprintf("target entity %s not found in entity_map; skipping edge", le.TargetLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	// 3. Reject self-loops up front — files-svc would reject
	// these with INVALID_ARGUMENT anyway. Only do this when both
	// endpoints actually resolved (otherwise the empty-string
	// equality is meaningless).
	if !skip && out.SourceEntityID != "" && out.SourceEntityID == out.TargetEntityID {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason: fmt.Sprintf(
				"source and target resolve to the same entity %s (self-loop); skipping edge",
				out.SourceEntityID,
			),
			Severity: SeverityError,
		})
		skip = true
	}

	// 4. Resolve relationship type.
	if le.RelationshipType == "" {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   "legacy edge has empty relationship_type; cannot resolve type_id",
			Severity: SeverityError,
		})
		skip = true
	} else {
		typeKey := fmt.Sprintf("legacy:rel-type:%d:%s", legacyOrgID, le.RelationshipType)
		if newTypeID, ok := relTypeIDLookup[typeKey]; ok && newTypeID != "" {
			out.RelationshipTypeID = newTypeID
		} else {
			notes = append(notes, RejectionNote{
				LegacyID: le.LegacyID,
				Reason: fmt.Sprintf(
					"relationship type %q not found in relationship_type_map (key=%s); skipping edge",
					le.RelationshipType, typeKey,
				),
				Severity: SeverityError,
			})
			skip = true
		}
	}

	// 5. Convert properties → structpb.Struct. Best-effort — drop
	// values structpb cannot represent, but still migrate the edge.
	if len(le.Properties) > 0 {
		filtered := make(map[string]any, len(le.Properties))
		for k, v := range le.Properties {
			cleaned, ok := normalizeStructValue(v)
			if !ok {
				notes = append(notes, RejectionNote{
					LegacyID: le.LegacyID,
					Reason:   fmt.Sprintf("property %q has unsupported type %T; dropping", k, v),
				})
				continue
			}
			filtered[k] = cleaned
		}
		if len(filtered) > 0 {
			s, err := structpb.NewStruct(filtered)
			if err != nil {
				notes = append(notes, RejectionNote{
					LegacyID: le.LegacyID,
					Reason:   fmt.Sprintf("structpb.NewStruct failed: %v; properties dropped", err),
				})
			} else {
				out.Properties = s
			}
		}
	}

	return out, notes, skip
}


--- services/migrator-files/internal/mapper/embedding.go (42 lines) ---
package mapper

import (
	"fmt"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EmbeddingMigrateInput is the mapper's normalized view of a single
// (chunk, vector) pair, shaped to feed
// DocumentService.MigrateChunkEmbeddings. Decision 9c: copy verbatim;
// never re-embed. The migrator forwards Vector + EmbeddingModel as-is
// from the legacy source.
//
// LegacyID is the synthesized "legacy:chunk:<int>" key — same shape
// as Phase 5's chunk_legacy_id. The handler joins on this to find
// the new chunk row and write the embedding_id back.
type EmbeddingMigrateInput struct {
	LegacyID       string // "legacy:chunk:<int>"
	Vector         []float32
	EmbeddingModel string
}

// EmbeddingsToMigrateInputs maps a slice of legacy embeddings (one per
// chunk in a single document) into the proto-shaped input slice.
// Preserves input ordering and never returns nil for a non-empty
// input.
func EmbeddingsToMigrateInputs(embeddings []legacy.LegacyChunkEmbedding) []EmbeddingMigrateInput {
	if len(embeddings) == 0 {
		return nil
	}
	out := make([]EmbeddingMigrateInput, 0, len(embeddings))
	for _, e := range embeddings {
		out = append(out, EmbeddingMigrateInput{
			LegacyID:       fmt.Sprintf("legacy:chunk:%d", e.LegacyChunkID),
			Vector:         e.Vector,
			EmbeddingModel: e.EmbeddingModel,
		})
	}
	return out
}


