// Package mapper converts legacy DTOs to proto messages.
package mapper

import (
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	entitytypev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/files/entity_type/v1"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EntityTypesToBootstrapItems maps legacy taxonomy entries to
// EntityType.Bootstrap items. Per-org types: pass orgID (UUID string);
// pass empty string for platform defaults (none on the migration path).
func EntityTypesToBootstrapItems(types []legacy.EntityType, orgID string) []*entitytypev1.BootstrapRequest_Item {
	out := make([]*entitytypev1.BootstrapRequest_Item, 0, len(types))
	for _, t := range types {
		item := &entitytypev1.BootstrapRequest_Item{
			Name:        t.Name,
			Description: t.Description,
			Color:       t.Color,
			Icon:        t.Icon,
			LegacyId:    &commonv1.LegacyID{Value: t.LegacyID},
		}
		if orgID != "" {
			item.OrgId = &commonv1.OrgID{Value: orgID}
		}
		out = append(out, item)
	}
	return out
}


