func TestCorpusToMigrateInput_Visibility(t *testing.T) {
	created := time.Date(2024, 1, 2, 3, 4, 5, 0, time.UTC)
	cases := []struct {
		name       string
		visibility string
		wantVis    corpusv1.CorpusVisibility
		wantNotes  int // visibility note + always-deferred-owner note
		wantReason string
	}{
		{"private", "private", corpusv1.CorpusVisibility_CORPUS_VISIBILITY_PRIVATE, 1, ""},
		{"team", "team", corpusv1.CorpusVisibility_CORPUS_VISIBILITY_TEAM, 1, ""},
		{"shared_downgrades_to_team", "shared", corpusv1.CorpusVisibility_CORPUS_VISIBILITY_TEAM, 2, "shared visibility deprecated"},
		{"unknown_defaults_to_private", "weird", corpusv1.CorpusVisibility_CORPUS_VISIBILITY_PRIVATE, 2, "unknown visibility"},
		{"empty_defaults_to_private", "", corpusv1.CorpusVisibility_CORPUS_VISIBILITY_PRIVATE, 2, "unknown visibility"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			in := legacy.LegacyCorpus{
				LegacyID: 42, Name: "c", Description: "desc",
				Visibility: tc.visibility, CreatedAt: created,
			}
			out, notes := mapper.CorpusToMigrateInput(in)
			assert.Equal(t, "legacy:corpus:42", out.LegacyID)
			assert.Equal(t, "c", out.Name)
			assert.Equal(t, "desc", out.Description)
			assert.Equal(t, tc.wantVis, out.Visibility)
			assert.Empty(t, out.OwnerUserID, "owner_user_id always deferred")
			require.NotNil(t, out.CreatedAt)
			assert.Equal(t, created.UTC(), out.CreatedAt.AsTime().UTC())
			require.Len(t, notes, tc.wantNotes)

			// last note is always the deferred-owner note
			last := notes[len(notes)-1]
			assert.Contains(t, last.Reason, "owner_user_id deferred")

			if tc.wantReason != "" {
				assert.Contains(t, notes[0].Reason, tc.wantReason)
