func TestEntityToMigrateInput_Happy(t *testing.T) {
	created := time.Date(2024, 6, 1, 0, 0, 0, 0, time.UTC)
	props := map[string]any{
		"age":     42,
		"flag":    true,
		"name":    "Alice",
		"score":   3.14,
		"tags":    []any{"a", "b"},
		"nested":  map[string]any{"k": "v"},
		"empty":   nil,
	}
	in := legacy.LegacyEntity{
		LegacyID: "legacy:entity:101", Label: "Alice", TypeName: "PERSON",
		Description: "a person", Properties: props, CreatedAt: created,
		LegacyCorpusIDs: []int64{2, 1, 99},
	}
	typeMap := map[string]string{"legacy:entity-type:1:PERSON": "et-uuid"}
	corpusMap := map[string]string{
		"legacy:corpus:1": "c1", "legacy:corpus:2": "c2",
	}
	out, notes := mapper.EntityToMigrateInput(in, 1, typeMap, corpusMap)

	assert.Equal(t, "legacy:entity:101", out.LegacyID)
	assert.Equal(t, "Alice", out.Label)
	assert.Equal(t, "et-uuid", out.TypeID)
	assert.Equal(t, "a person", out.Description)
	require.NotNil(t, out.CreatedAt)

	// Corpus order is sorted ascending: 1, 2; 99 unmapped → note.
	require.Len(t, out.CorpusIDs, 2)
	assert.Equal(t, "c1", out.CorpusIDs[0])
	assert.Equal(t, "c2", out.CorpusIDs[1])

	// One note for the unmapped corpus 99.
	require.Len(t, notes, 1)
	assert.Contains(t, notes[0].Reason, "legacy:corpus:99")

	// Properties became a struct.
	require.NotNil(t, out.Properties)
	assert.Contains(t, out.Properties.GetFields(), "age")
	assert.Contains(t, out.Properties.GetFields(), "tags")
	assert.Contains(t, out.Properties.GetFields(), "nested")
}

