// ----------------------------------------------------------------------
// helpers
// ----------------------------------------------------------------------

// containsAny is a tiny substring helper; testify has Contains but we
// already use it elsewhere — kept here to avoid sprinkling import
// blocks for a one-liner.
func containsAny(s, sub string) bool {
	return len(sub) == 0 || (len(s) >= len(sub) && indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}


