package mapper

import (
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	relationshiptypev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/files/relationship_type/v1"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// RelationshipTypesToBootstrapItems maps legacy relationship taxonomy
// entries to RelationshipType.Bootstrap items. Legacy stores relationship
// types as Memgraph edge labels — they are synthesized via DISTINCT
// type(r) and keyed by legacy_id "legacy:rel-type:<org_id>:<name>".
//
// Per-org types: pass orgID (UUID string); pass empty string for
// platform defaults (none on the migration path). All legacy edges are
// directed, so IsDirected is set to true for every entry.
func RelationshipTypesToBootstrapItems(types []legacy.RelationshipType, orgID string) []*relationshiptypev1.BootstrapRequest_Item {
	out := make([]*relationshiptypev1.BootstrapRequest_Item, 0, len(types))
	for _, t := range types {
		item := &relationshiptypev1.BootstrapRequest_Item{
			Name:        t.Name,
			Description: t.Description,
			IsDirected:  t.IsDirected,
			LegacyId:    &commonv1.LegacyID{Value: t.LegacyID},
		}
		if orgID != "" {
			item.OrgId = &commonv1.OrgID{Value: orgID}
		}
		out = append(out, item)
	}
	return out
}



