package mapper

import (
	"fmt"
	"strings"

	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// DocumentMigrateInput is the mapper's normalized view of a legacy
// document, shaped to feed DocumentService.MigrateUpload.
//
// CorpusID is the new-platform UUID resolved upstream from the corpus
// legacy_id_map (Phase 3 sidecar). UploadedBy is left empty when the
// legacy row has a NULL uploaded_by — the apply layer skips those rows
// because files-svc rejects empty uploaded_by with INVALID_ARGUMENT.
type DocumentMigrateInput struct {
	LegacyID         string // "legacy:document:<int>"
	CorpusID         string // new-platform corpus UUID
	OriginalFilename string
	MIMEType         string // RFC-6838 media type
	SizeBytes        int64
	UploadedBy       string // new-platform user UUID; empty until user-resolution lands
	CreatedAt        *timestamppb.Timestamp
}

// DocumentToMigrateInput maps a legacy.LegacyDocument to a MigrateUpload
// RPC input plus a slice of soft rejection notes for owner-resolution
// deferrals and unknown file types.
//
// Note ordering is intentional: deferred-owner / unknown-mime notes
// always precede any per-row downstream notes appended by the apply
// layer (size mismatch, RPC failure, etc.).
//
// uploaded_by is intentionally left empty for the same reason as
// CorpusToMigrateInput: legacy users.id is an INTEGER FK, the new
// platform stores uploaded_by as a UUID. The user-resolution layer is
// deferred; the apply layer skips legacy rows with a nil uploaded_by
// because files-svc requires a non-empty value.
func DocumentToMigrateInput(ld legacy.LegacyDocument, corpusUUID string) (DocumentMigrateInput, []RejectionNote) {
	legacyID := fmt.Sprintf("legacy:document:%d", ld.LegacyID)
	var notes []RejectionNote

	mime := resolveMIMEType(ld.MIMEType)
	if mime == "application/octet-stream" && ld.MIMEType != "" {
		notes = append(notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("unknown legacy file_type %q; defaulted to application/octet-stream", ld.MIMEType),
		})
	}

	notes = append(notes, RejectionNote{
		LegacyID: legacyID,
		Reason:   "uploaded_by deferred — legacy int FK not resolved to new UUID",
	})

	return DocumentMigrateInput{
		LegacyID:         legacyID,
		CorpusID:         corpusUUID,
		OriginalFilename: ld.OriginalFilename,
		MIMEType:         mime,
		SizeBytes:        ld.SizeBytes,
		UploadedBy:       "",
		CreatedAt:        timestamppb.New(ld.CreatedAt),
	}, notes
}

// resolveMIMEType maps the legacy `documents.file_type` short tag (e.g.
// "pdf", "docx", "txt") to a real RFC-6838 mime type. Unknown / empty
// values resolve to application/octet-stream — the new-platform schema
// uses that as the safe default for opaque binaries.
func resolveMIMEType(legacyFileType string) string {
	switch strings.ToLower(strings.TrimSpace(legacyFileType)) {
	case "":
		return "application/octet-stream"
	case "pdf":
		return "application/pdf"
	case "txt", "text":
		return "text/plain"
	case "md", "markdown":
		return "text/markdown"
	case "html", "htm":
		return "text/html"
	case "csv":
		return "text/csv"
	case "json":
		return "application/json"
	case "doc":
		return "application/msword"
	case "docx":
		return "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
	case "xls":
		return "application/vnd.ms-excel"
	case "xlsx":
		return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
	case "ppt":
		return "application/vnd.ms-powerpoint"
	case "pptx":
		return "application/vnd.openxmlformats-officedocument.presentationml.presentation"
	case "png":
		return "image/png"
	case "jpg", "jpeg":
		return "image/jpeg"
	case "gif":
		return "image/gif"
	case "mp3":
		return "audio/mpeg"
	case "wav":
		return "audio/wav"
	case "mp4":
		return "video/mp4"
	default:
		// Already a real mime type? Pass it through.
		if strings.Contains(legacyFileType, "/") {
			return legacyFileType
		}
		return "application/octet-stream"
	}
}

// SanitizeStorageKey strips path separators and other characters that
// would break a flat MinIO key from a legacy filename. Empty input
// yields "file" (so the key always carries a trailing component).
func SanitizeStorageKey(filename string) string {
	if filename == "" {
		return "file"
	}
	mapping := func(r rune) rune {
		switch {
		case r == '/' || r == '\\':
			return '_'
		case r < 0x20 || r == 0x7f:
			return '_'
		default:
			return r
		}
	}
	out := strings.Map(mapping, filename)
	out = strings.TrimSpace(out)
	if out == "" {
		return "file"
	}
	return out
}


