package mapper

import (
	"fmt"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EmbeddingMigrateInput is the mapper's normalized view of a single
// (chunk, vector) pair, shaped to feed
// DocumentService.MigrateChunkEmbeddings. Decision 9c: copy verbatim;
// never re-embed. The migrator forwards Vector + EmbeddingModel as-is
// from the legacy source.
//
// LegacyID is the synthesized "legacy:chunk:<int>" key — same shape
// as Phase 5's chunk_legacy_id. The handler joins on this to find
// the new chunk row and write the embedding_id back.
type EmbeddingMigrateInput struct {
	LegacyID       string // "legacy:chunk:<int>"
	Vector         []float32
	EmbeddingModel string
}

// EmbeddingsToMigrateInputs maps a slice of legacy embeddings (one per
// chunk in a single document) into the proto-shaped input slice.
// Preserves input ordering and never returns nil for a non-empty
// input.
func EmbeddingsToMigrateInputs(embeddings []legacy.LegacyChunkEmbedding) []EmbeddingMigrateInput {
	if len(embeddings) == 0 {
		return nil
	}
	out := make([]EmbeddingMigrateInput, 0, len(embeddings))
	for _, e := range embeddings {
		out = append(out, EmbeddingMigrateInput{
			LegacyID:       fmt.Sprintf("legacy:chunk:%d", e.LegacyChunkID),
			Vector:         e.Vector,
			EmbeddingModel: e.EmbeddingModel,
		})
	}
	return out
}


