package mapper

import (
	"fmt"
	"sort"

	"google.golang.org/protobuf/types/known/structpb"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EntityMigrateInput is the mapper's normalized view of a legacy
// `:Entity` node, shaped to feed EntityService.MigrateEntity.
//
// TypeID is the new-platform UUID resolved via the Phase 1 sidecar
// (entity_type_map.json). When Resolve fails, the caller should drop
// the entity — files-svc rejects MigrateEntity with empty type_id.
//
// CorpusIDs is the resolved set of new-platform corpus UUIDs (via the
// Phase 3 sidecar). Empty when the legacy entity has no corpus
// associations or when none of its associations resolved.
//
// CreatedAt is the legacy `e.created` LocalDateTime carried over for
// future schema work; the current MigrateEntity proto does not accept
// it, so the apply layer omits it from the request. We still surface it
// here for symmetry with the rest of the migrator + a future-proofing
// reason: when the proto adds it, no mapper change is needed.
type EntityMigrateInput struct {
	LegacyID    string
	Label       string
	TypeID      string
	Description string
	Properties  *structpb.Struct
	CorpusIDs   []string
	CreatedAt   *timestamppb.Timestamp
}

// EntityToMigrateInput maps a legacy.LegacyEntity to a MigrateEntity RPC
// input plus a slice of soft rejection notes for unresolved type or
// corpus references.
//
// Type resolution:
//
//	The legacy `type` field is a free-form string (e.g. "PERSON"). Phase
//	1 (entity-types apply) bootstrapped each distinct type into
//	files.entity_types and emitted entity_type_map.json keyed by
//	"legacy:entity-type:<legacyOrgID>:<TypeName>" (see
//	memgraph.go::ListEntityTypes for the canonical key shape).
//
//	When the type is not present in typeIDLookup we emit a rejection
//	note and return TypeID == "". The caller MUST treat this as "skip
//	entity" — files-svc rejects empty type_id.
//
// Corpus resolution:
//
//	Each LegacyCorpusIDs element is formatted as "legacy:corpus:<int>"
//	(matching corpus.go's key shape) and looked up in corpusLookup.
//	Unmapped entries are dropped with a soft note. An entity with all
//	corpus refs unmapped still migrates — corpus_ids is allowed to be
//	empty (orphan entity) per the proto.
//
// Properties conversion:
//
//	legacy.LegacyEntity.Properties is map[string]any; we convert to
//	*structpb.Struct for the proto. structpb.NewStruct supports nested
//	maps, slices, primitives, time.Time-as-string round-trip is the
//	caller's responsibility (Memgraph stores most values as primitives).
//	Unconvertible values trigger a single rejection note and are
//	dropped from the resulting Properties; the entity still migrates
//	with a partial property set.
//
// legacyOrgID is the integer organization_id used when Phase 1 minted
// the entity-type LegacyID keys — pass the same value here so lookups
// hit.
func EntityToMigrateInput(
	le legacy.LegacyEntity,
	legacyOrgID int,
	typeIDLookup map[string]string,
	corpusLookup map[string]string,
) (EntityMigrateInput, []RejectionNote) {
	var notes []RejectionNote

	out := EntityMigrateInput{
		LegacyID:    le.LegacyID,
		Label:       le.Label,
		Description: le.Description,
	}
	if !le.CreatedAt.IsZero() {
		out.CreatedAt = timestamppb.New(le.CreatedAt)
	}

	// 1. Resolve type.
	if le.TypeName == "" {
		notes = append(notes, RejectionNote{
			LegacyID: le.LegacyID,
			Reason:   "legacy entity has empty type; cannot resolve type_id",
			Severity: SeverityError,
		})
	} else {
		typeKey := fmt.Sprintf("legacy:entity-type:%d:%s", legacyOrgID, le.TypeName)
		if newTypeID, ok := typeIDLookup[typeKey]; ok && newTypeID != "" {
			out.TypeID = newTypeID
		} else {
			notes = append(notes, RejectionNote{
				LegacyID: le.LegacyID,
				Reason:   fmt.Sprintf("entity type %q not found in entity_type_map (key=%s); skipping entity", le.TypeName, typeKey),
				Severity: SeverityError,
			})
		}
	}

	// 2. Resolve corpora. Sort the input slice so the resulting
	// CorpusIDs is deterministic across re-runs.
	if len(le.LegacyCorpusIDs) > 0 {
		ids := append([]int64(nil), le.LegacyCorpusIDs...)
		sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
		for _, lcID := range ids {
			corpusKey := fmt.Sprintf("legacy:corpus:%d", lcID)
			if newCorpusID, ok := corpusLookup[corpusKey]; ok && newCorpusID != "" {
				out.CorpusIDs = append(out.CorpusIDs, newCorpusID)
				continue
			}
			notes = append(notes, RejectionNote{
				LegacyID: le.LegacyID,
				Reason:   fmt.Sprintf("corpus %s not found in corpus_map; dropping membership", corpusKey),
			})
		}
	}

	// 3. Convert properties → structpb.Struct. structpb.NewStruct
	// rejects unsupported types as a whole; pre-filter to keep
	// well-typed values.
	if len(le.Properties) > 0 {
		filtered := make(map[string]any, len(le.Properties))
		for k, v := range le.Properties {
			cleaned, ok := normalizeStructValue(v)
			if !ok {
				notes = append(notes, RejectionNote{
					LegacyID: le.LegacyID,
					Reason:   fmt.Sprintf("property %q has unsupported type %T; dropping", k, v),
				})
				continue
			}
			filtered[k] = cleaned
		}
		if len(filtered) > 0 {
			s, err := structpb.NewStruct(filtered)
			if err != nil {
				notes = append(notes, RejectionNote{
					LegacyID: le.LegacyID,
					Reason:   fmt.Sprintf("structpb.NewStruct failed: %v; properties dropped", err),
				})
			} else {
				out.Properties = s
			}
		}
	}

	return out, notes
}

// normalizeStructValue coerces a Memgraph-returned property value into
// something structpb.NewStruct accepts (bool, float64, string, []any,
// map[string]any, nil). Returns (cleaned, true) on success, (nil,
// false) when the value cannot be represented as a structpb scalar.
func normalizeStructValue(v any) (any, bool) {
	switch x := v.(type) {
	case nil, bool, string, float64, float32, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return x, true
	case []any:
		out := make([]any, 0, len(x))
		for _, el := range x {
			c, ok := normalizeStructValue(el)
			if !ok {
				return nil, false
			}
			out = append(out, c)
		}
		return out, true
	case map[string]any:
		out := make(map[string]any, len(x))
		for k, el := range x {
			c, ok := normalizeStructValue(el)
			if !ok {
				return nil, false
			}
			out[k] = c
		}
		return out, true
	default:
		return nil, false
	}
}


