package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/structpb"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
)

// EntityProvenanceMigrateInput is the mapper's normalized view of an
// entity↔chunk provenance link, shaped to feed
// EntityService.MigrateProvenance.Link.
//
// EntityID is the new-platform UUID resolved via the Phase 7 sidecar
// (entity_map.json), keyed "legacy:entity:<int64>". ChunkID is the
// new-platform UUID resolved via the Phase 5 sidecar (chunk_map.json),
// keyed "legacy:chunk:<int64>". When either lookup misses the caller
// MUST drop the link.
//
// Confidence defaults to 1.0 when legacy did not track a per-link
// confidence — the new platform's `entity_provenance.confidence`
// column is NOT NULL.
//
// Properties is reserved for future expansion; the proto's Link
// message has no struct field today, so the mapper does not forward
// it. Surfaced on the input for symmetry + diagnostic logs.
type EntityProvenanceMigrateInput struct {
	LegacyID   string // mirrors source legacy_id for note correlation
	EntityID   string
	ChunkID    string
	Confidence float32
	Properties *structpb.Struct
}

// EdgeProvenanceMigrateInput is the mapper's normalized view of an
// edge↔chunk provenance link, shaped to feed
// EdgeService.MigrateProvenance.Link.
//
// Resolution rules mirror EntityProvenanceMigrateInput, except the
// source-side lookup is the Phase 8 sidecar (edge_map.json), keyed
// "legacy:edge:<int64>".
type EdgeProvenanceMigrateInput struct {
	LegacyID   string
	EdgeID     string
	ChunkID    string
	Confidence float32
	Properties *structpb.Struct
}

// EntityProvenanceToMigrateInput maps a legacy.ProvenanceLink to an
// entity-side migrate input plus a slice of soft rejection notes. The
// third return value is a hard `skip` flag — when true the caller
// MUST drop the link.
//
// Resolution:
//
//	 1. SourceLegacyID → entityIDLookup. Empty or missing → skip
//	    with note.
//	 2. ChunkLegacyID → chunkIDLookup. Empty or missing → skip with
//	    note.
//	 3. Confidence: if zero (legacy didn't set), default to 1.0.
//	    Out-of-range values are clamped to [0,1] and noted.
//	 4. Properties: best-effort convert via normalizeStructValue —
//	    same helper as EntityToMigrateInput. Currently unused
//	    downstream because the proto Link has no Struct field; we
//	    still produce it for forward-compat.
func EntityProvenanceToMigrateInput(
	p legacy.ProvenanceLink,
	entityIDLookup map[string]string,
	chunkIDLookup map[string]string,
) (EntityProvenanceMigrateInput, []RejectionNote, bool) {
	var notes []RejectionNote
	out := EntityProvenanceMigrateInput{LegacyID: p.SourceLegacyID}
	skip := false

	if p.SourceLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   "entity provenance has empty source legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := entityIDLookup[p.SourceLegacyID]; ok && newID != "" {
		out.EntityID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   fmt.Sprintf("entity %s not found in entity_map; skipping provenance link", p.SourceLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	if p.ChunkLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   "entity provenance has empty chunk legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := chunkIDLookup[p.ChunkLegacyID]; ok && newID != "" {
		out.ChunkID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   fmt.Sprintf("chunk %s not found in chunk_map; skipping provenance link", p.ChunkLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	out.Confidence = clampConfidence(p.Confidence, p.SourceLegacyID, &notes)

	out.Properties = normalizeProvenanceProps(p.Properties, p.SourceLegacyID, &notes)

	return out, notes, skip
}

// EdgeProvenanceToMigrateInput maps a legacy.ProvenanceLink to an
// edge-side migrate input plus a slice of soft rejection notes. The
// third return value is a hard `skip` flag — when true the caller
// MUST drop the link.
//
// Mirrors EntityProvenanceToMigrateInput but resolves the source-side
// id through the Phase 8 sidecar (edge_map.json).
func EdgeProvenanceToMigrateInput(
	p legacy.ProvenanceLink,
	edgeIDLookup map[string]string,
	chunkIDLookup map[string]string,
) (EdgeProvenanceMigrateInput, []RejectionNote, bool) {
	var notes []RejectionNote
	out := EdgeProvenanceMigrateInput{LegacyID: p.SourceLegacyID}
	skip := false

	if p.SourceLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   "edge provenance has empty source legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := edgeIDLookup[p.SourceLegacyID]; ok && newID != "" {
		out.EdgeID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   fmt.Sprintf("edge %s not found in edge_map; skipping provenance link", p.SourceLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	if p.ChunkLegacyID == "" {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   "edge provenance has empty chunk legacy_id; skipping",
			Severity: SeverityError,
		})
		skip = true
	} else if newID, ok := chunkIDLookup[p.ChunkLegacyID]; ok && newID != "" {
		out.ChunkID = newID
	} else {
		notes = append(notes, RejectionNote{
			LegacyID: p.SourceLegacyID,
			Reason:   fmt.Sprintf("chunk %s not found in chunk_map; skipping provenance link", p.ChunkLegacyID),
			Severity: SeverityError,
		})
		skip = true
	}

	out.Confidence = clampConfidence(p.Confidence, p.SourceLegacyID, &notes)

	out.Properties = normalizeProvenanceProps(p.Properties, p.SourceLegacyID, &notes)

	return out, notes, skip
}

// clampConfidence enforces the [0,1] invariant the new platform's
// `*_provenance.confidence` columns require, defaulting unset values
// (zero) to 1.0 since legacy did not track a per-link confidence.
func clampConfidence(c float32, legacyID string, notes *[]RejectionNote) float32 {
	if c <= 0 {
		// Treat zero/negative as "unset" — legacy default is 1.0.
		return 1.0
	}
	if c > 1.0 {
		*notes = append(*notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("confidence %f out of range; clamping to 1.0", c),
		})
		return 1.0
	}
	return c
}

// normalizeProvenanceProps converts opaque legacy properties into a
// *structpb.Struct on a best-effort basis. Values structpb cannot
// represent are dropped with a soft note.
func normalizeProvenanceProps(props map[string]any, legacyID string, notes *[]RejectionNote) *structpb.Struct {
	if len(props) == 0 {
		return nil
	}
	filtered := make(map[string]any, len(props))
	for k, v := range props {
		cleaned, ok := normalizeStructValue(v)
		if !ok {
			*notes = append(*notes, RejectionNote{
				LegacyID: legacyID,
				Reason:   fmt.Sprintf("provenance property %q has unsupported type %T; dropping", k, v),
			})
			continue
		}
		filtered[k] = cleaned
	}
	if len(filtered) == 0 {
		return nil
	}
	s, err := structpb.NewStruct(filtered)
	if err != nil {
		*notes = append(*notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("structpb.NewStruct failed: %v; properties dropped", err),
		})
		return nil
	}
	return s
}


